/**
 * @distilled.cloud/railway — Railway SDK for Effect.
 *
 * Railway is one GraphQL endpoint. There are no per-service modules
 * (no SQS / R2 / Machines split). Operations live on the package root.
 *
 * `./services/railway.ts` is generated by `scripts/generate.ts` from the
 * Smithy model in `.generated-specs` (GraphQL introspection →
 * `scripts/convert.ts`). Everything else in this folder is hand-written.
 *
 * @example
 * ```ts
 * import * as Railway from "@distilled.cloud/railway";
 *
 * yield* Railway.projectCreate({ input: { name: "demo" } });
 * yield* Railway.serviceCreate({
 *   input: { projectId, source: { image: "hashicorp/http-echo" } },
 * });
 * yield* Railway.me({});
 * ```
 *
 * GraphQL field names are the spec (`projectCreate`, not `createProject`).
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  RailwayGraphqlProtocol,
  type RailwayOpError,
  type RailwayOpContext,
} from "./protocol.ts";
export * as Pagination from "./pagination.ts";
export * as Retry from "./retry.ts";
export * from "./services/railway.ts";
